import {element,validate} from './model.js';
import {appearance} from './design.js';
import {behavior} from './components.js';

const LIMIT=1024*1024,DEPTH=40;
const MODULES={
 'hyprland/workspaces':'workspaces','hyprland/window':'launcher',clock:'clock',wireplumber:'volume',pulseaudio:'volume',network:'network',bluetooth:'bluetooth',battery:'battery',upower:'battery','custom/notification':'notifications',mpris:'music',cpu:'cpu',memory:'memory','custom/power':'power'
};
export function parseJsonc(text){if(typeof text!=='string'||text.length>LIMIT)throw Error('Waybar config exceeds 1 MB');let out='',string=false,quote='',escape=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(string){out+=c;if(escape)escape=false;else if(c==='\\')escape=true;else if(c===quote)string=false;continue;}if(c==='"'||c==="'"){string=true;quote=c;out+=c;continue;}if(c==='/'&&n==='/'){while(i<text.length&&text[i]!=='\n')i++;out+='\n';continue;}if(c==='/'&&n==='*'){i+=2;while(i<text.length-1&&!(text[i]==='*'&&text[i+1]==='/'))i++;i++;continue;}out+=c;}out=out.replace(/,\s*([}\]])/g,'$1');const value=JSON.parse(out);checkDepth(value);return value;}
function checkDepth(value,depth=0){if(depth>DEPTH)throw Error('Waybar config nesting is too deep');if(value&&typeof value==='object')for(const v of Object.values(value))checkDepth(v,depth+1);}
function safeText(v,max=240){return typeof v==='string'?v.slice(0,max):'';}
export function importWaybar(configText,cssText=''){
 const source=parseJsonc(configText),bars=Array.isArray(source)?source:[source],first=bars[0];if(!first||typeof first!=='object')throw Error('Waybar config must contain a bar object');
 const p={format:'ricing-town',version:3,name:'Imported Waybar',canvas:{width:1920,height:1080,background:'#111820'},elements:[],assets:[],runtime:{audioTarget:'default',mediaPlayer:'auto',monitor:'auto'},extensions:{imports:{waybar:{preserved:{},unsafe:[],report:[]}}}};
 const report={imported:[],approximated:[],unsupported:[],disabled:[],missing:[]},position=first.position==='bottom'?'bottom':'top',height=Number.isInteger(first.height)?Math.max(20,Math.min(200,first.height)):40;
 const bar=element('bar',Number(first['margin-left'])||8,position==='top'?(Number(first['margin-top'])||8):1080-height-(Number(first['margin-bottom'])||8));bar.name='Imported Waybar';bar.width=1920-(Number(first['margin-left'])||8)-(Number(first['margin-right'])||8);bar.height=height;bar.anchorX='stretch';bar.anchorY=position;bar.options={...bar.options,gap:Number.isFinite(first.spacing)?Math.max(0,Math.min(100,first.spacing)):8,items:[]};p.elements.push(bar);
 const groups=[['modules-left','start'],['modules-center','center'],['modules-right','end']];let cursor=12;for(const [key,align] of groups){for(const raw of Array.isArray(first[key])?first[key]:[]){if(typeof raw!=='string')continue;const base=raw.split('#')[0],type=MODULES[base];if(!type){report.unsupported.push(`Module ${raw}`);p.extensions.imports.waybar.preserved[raw]=first[raw]||{};continue;}const e=element(type,cursor,4);e.parentId=bar.id;e.name=raw;e.height=Math.max(20,height-8);e.width=type==='workspaces'?220:type==='clock'||type==='music'?180:125;e.fontSize=Number(first[raw]?.['format-icons']?.length)?16:14;e.options={...e.options,padding:6,gap:6,align};const cfg=first[raw]||first[base]||{};if(typeof cfg.format==='string')e.importedFormat=safeText(cfg.format);if(Number.isFinite(cfg.interval))e.refreshInterval=Math.max(1,Math.min(86400,cfg.interval));for(const actionKey of ['on-click','on-click-right','on-click-middle','on-scroll-up','on-scroll-down'])if(cfg[actionKey]){e.importedUnsafe??={};e.importedUnsafe[actionKey]=safeText(cfg[actionKey],500);report.disabled.push(`${raw}.${actionKey}: command preserved but disabled`);}p.elements.push(e);cursor+=e.width+bar.options.gap;report.imported.push(`${raw} → ${type}`);}
 }
 if(bars.length>1)report.approximated.push('Only the first Waybar bar was converted; remaining bars were preserved in metadata.');if(bars.length>1)p.extensions.imports.waybar.preserved.additionalBars=bars.slice(1);
 const css=importWaybarCss(cssText,report);if(css.rules.length){for(const e of p.elements)e.waybarStyle=css.forModule(e.name,e.type);report.imported.push(`${css.rules.length} safe GTK CSS rules`);}p.extensions.imports.waybar.report=report;return {project:validate(p),report};
}
export function importWaybarCss(text,report={disabled:[],unsupported:[]}){if(typeof text!=='string'||text.length>LIMIT)throw Error('Waybar CSS exceeds 1 MB');const cleaned=text.replace(/\/\*[\s\S]*?\*\//g,'');if(/@import/i.test(cleaned))report.disabled.push('CSS @import was disabled');const rules=[];for(const match of cleaned.replace(/@import[^;]+;/gi,'').matchAll(/([^{}]+)\{([^{}]*)\}/g)){const selector=match[1].trim(),decl={};if(!/^[-#.*\w\s,:>+\[\]="']+$/.test(selector)){report.unsupported.push(`CSS selector ${selector}`);continue;}for(const part of match[2].split(';')){const i=part.indexOf(':');if(i<1)continue;const key=part.slice(0,i).trim(),value=part.slice(i+1).trim();if(!['color','background','background-color','font-family','font-size','font-weight','padding','margin','border','border-radius','opacity','min-width','min-height'].includes(key))continue;if(/url\s*\(|expression|@import|javascript:/i.test(value)){report.disabled.push(`Unsafe CSS value in ${selector}`);continue;}decl[key]=value.slice(0,200);}if(Object.keys(decl).length)rules.push({selector,declarations:decl});}return {rules,forModule(name,type){const ids=[`#${name.replace('/','-').replace(/#.+$/,'')}`,`#${type}`];return Object.assign({},...rules.filter(r=>ids.some(id=>r.selector.split(',').some(s=>s.trim()===id))).map(r=>r.declarations));}};}

const waybarName=e=>({workspaces:'hyprland/workspaces',clock:'clock',volume:'wireplumber',brightness:'backlight',network:'network',bluetooth:'bluetooth',battery:'battery',notifications:'custom/notification',music:'mpris',cpu:'cpu',memory:'memory',temperature:'temperature',disk:'disk',power:'custom/power'}[e.type]||null);
export function exportWaybar(project){const p=validate(project),report={supported:[],approximated:[],unsupported:[],security:[]},root=p.elements.find(e=>e.type==='bar'||e.type==='dock'),children=root?p.elements.filter(e=>e.parentId===root.id):p.elements.filter(e=>waybarName(e));const modules=[];const config={layer:'top',position:(root?.anchorY==='bottom'||root?.y>p.canvas.height/2)?'bottom':'top',height:Math.round(root?.height||40),spacing:Math.round(root?.options?.gap||8),'modules-left':[],'modules-center':[],'modules-right':[]};for(const e of children){const name=waybarName(e);if(!name){report.unsupported.push(`${e.name}: ${e.type} has no native Waybar module`);continue;}let unique=name;if(modules.includes(name))unique=name+'#'+e.id.slice(0,8);modules.push(name);const align=e.options?.align||'center',target=align==='start'?'modules-left':align==='end'?'modules-right':'modules-center';config[target].push(unique);const cfg={};if(e.importedFormat)cfg.format=e.importedFormat;if(e.refreshInterval)cfg.interval=e.refreshInterval;if(e.type==='workspaces')cfg['on-click']='activate';if(Object.keys(cfg).length)config[unique]=cfg;report.supported.push(`${e.name} → ${unique}`);if(e.appearance?.blur)report.unsupported.push(`${e.name}: backdrop blur`);if(e.appearance?.shadow)report.approximated.push(`${e.name}: shadow depends on GTK compositor support`);if(e.importedUnsafe)report.security.push(`${e.name}: imported commands omitted`);}
 if(root?.monitorId&&root.monitorId!=='all'){const monitor=p.monitors.find(m=>m.id===root.monitorId);if(monitor?.output){config.output=monitor.output;report.supported.push(`${root.name} → display ${monitor.output}`);}else report.approximated.push(`${root.name}: selected display has no output name, so Waybar uses its default output`);}
 for(const e of p.elements.filter(e=>['widget','text','shape'].includes(e.type)))if(!report.unsupported.some(x=>x.startsWith(e.name+':')))report.unsupported.push(`${e.name}: Widget Neighborhood composition requires Quickshell`);
 const selectors=children.map(e=>{const name=waybarName(e);if(!name)return '';const id='#'+name.replace('/','-');const a=appearance(e);return `${id} { color: ${e.color}; background-color: ${rgba(e.fill,a.opacity)}; border-radius: ${e.radius}px; border: ${a.borderWidth}px solid ${a.borderColor}; padding: ${e.options?.padding||0}px; font-family: ${gtkFont(a.font)}; font-size: ${e.fontSize}px; }`;}).filter(Boolean).join('\n');const css=`* { min-height: 0; }\nwindow#waybar { background: transparent; }\n${selectors}\n`;
 const readme=`# Ricing Town Waybar export\n\nGenerated for Waybar JSONC and GTK3 CSS. Review compatibility.json before applying. No imported shell commands or helper secrets are included.\n\n## Dry run\n\nRun \`sh install.sh --dry-run\` to print planned paths. Installation is never automatic.\n\n## Install\n\nRun \`sh install.sh --apply\`. Existing config and style files receive timestamped backups in the same directory. Then start Waybar with \`waybar -c ~/.config/waybar/config.jsonc -s ~/.config/waybar/style.css\`.\n\n## Restore\n\nStop Waybar, move the timestamped backup files back to their original names, then restart your prior Waybar service. Remove only files created by this package.\n`;
 return {files:{'config.jsonc':JSON.stringify(config,null,2),'style.css':css,'compatibility.json':JSON.stringify(report,null,2),'README.md':readme,'install.sh':installer()},report};}
function rgba(hex,opacity){const n=parseInt(hex.slice(1),16);return `rgba(${n>>16},${n>>8&255},${n&255},${Math.max(0,Math.min(1,opacity??1))})`;}
function gtkFont(font){return JSON.stringify(['sans-serif','serif','monospace'].includes(font)?font:'sans-serif');}
function installer(){return '#!/bin/sh\nset -eu\nmode="${1:---dry-run}"\ntarget="${XDG_CONFIG_HOME:-$HOME/.config}/waybar"\ncase "$mode" in --dry-run) echo "Would create $target and back up config.jsonc/style.css before copying.";; --apply) mkdir -p "$target"; stamp=$(date +%Y%m%d-%H%M%S); for f in config.jsonc style.css; do [ ! -e "$target/$f" ] || cp -a "$target/$f" "$target/$f.ricing-town-backup-$stamp"; cp "$f" "$target/$f"; done;; *) echo "Use --dry-run or --apply" >&2; exit 2;; esac\n';}
